import{z as d,x as p,o as r,c as A,q as o,j as l,D as e,d as t,s,S as E,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"平均情形与单向函数","description":"","frontmatter":{"title":"平均情形与单向函数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/one-way-functions-avg.md","filePath":"cs/one-way-functions-avg.md","lastUpdated":1791413859000}'),B={name:"cs/one-way-functions-avg.md"};function P(F,a,f,h,m,c){const i=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=o('<h1 id="平均情形与单向函数" tabindex="-1">平均情形与单向函数 <a class="header-anchor" href="#平均情形与单向函数" aria-label="Permalink to &quot;平均情形与单向函数&quot;">​</a></h1><div class="epigraph"><p>最坏 NP 完全不阻止「随机实例容易」。单向函数要求：正算易、反演在平均上难。密码学的存在性停在这一假设。</p><footer>—— 据 Levin；Goldreich, Foundations of Cryptography；Arora and Barak 整理</footer></div><p>上一课<a href="/cs/fpt-parameterized">FPT</a> 仍最坏。主干 NPC 与随机算法也不等于平均。缺口是：<strong>分布上的难</strong>，以及单向函数（OWF）。本课不设计协议；主干公钥课用过 Diffie–Hellman，这里给复杂度语言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Levin 的平均 NP：对多项式时间可抽样的分布，算法须在平均多项式（允许稀有极慢）。某些 NPC 问题在自然分布上有启发式；某些（如随机 3SAT 的缝隙相变）被认为难。OWF：\\(f\\) 多项式可算，对均匀 \\(x\\)，任意多项式对手反演 \\(f(x)\\) 的概率可忽略。OWF 存在 \\(\\Rightarrow P\\neq NP\\)，但更强：难在平均、在函数反演。伪随机发生器、签名的极小假设常落到 OWF 或陷门。</p><p>单向置换、陷门置换（RSA 形状）是加结构的 OWF。本课不分析模运算——那是数论单元。</p><h3 id="最坏到平均的归约稀缺" tabindex="-1">最坏到平均的归约稀缺 <a class="header-anchor" href="#最坏到平均的归约稀缺" aria-label="Permalink to &quot;最坏到平均的归约稀缺&quot;">​</a></h3><p>已知对某些问题（Ajtai 格、后课 LWE）最坏难 \\(\\Rightarrow\\) 平均难。一般 NPC 没有。不要写「SAT 随机实例所以密码安全」。</p><p><span class="marginnote">Levin 平均情形。Goldreich 的 OWF 定义。Håstad–Impagliazzo–Levin–Luby 从 OWF 做 PRG，点名不证。本课与 BPP 的「算法内硬币」分工：这里难的是对手面对的分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 OWF 的实验：挑战 \\(y=f(x)\\)，对手输出 \\(x&#39;\\)，\\(f(x&#39;)=y\\)。可忽略 \\(= n^{-\\omega(1)}\\)。对照 NP 证书：知道 \\(x\\) 是短证，但证书对诚实抽样仍难找。点名：单向不蕴涵陷门；加密需要更多。</p><p><span class="marginnote">术语翻译：「可忽略」就是比 \\(1/n\\)、\\(1/n^2\\)……任何多项式倒数都掉得快的量，比如 \\(2^{-128}\\)——宇宙里每个原子各当一台计算机、跑满宇宙年龄，撞中的机会仍约等于零。反过来，「易」只要求多项式时间，所以防御必须压到这个几乎为零的档位才算数。</span></p>',12)),(r(),l(E,null,{default:e(()=>[s(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WORST%5B%22%E6%9C%80%E5%9D%8F%20NP%22%5D%20--%3E%20DIST%5B%22%E5%88%86%E5%B8%83%20%2F%20%E5%B9%B3%E5%9D%87%22%5D%0A%20%20DIST%20--%3E%20OWF%5B%22%E5%8D%95%E5%90%91%E5%87%BD%E6%95%B0%22%5D%0A%20%20OWF%20--%3E%20PRG%5B%22%E4%BC%AA%E9%9A%8F%E6%9C%BA%20%2F%20%E5%90%8E%E8%AF%BE%E5%AF%86%E7%A0%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"若一切 OWF 都不存在，则许多私钥方案崩溃，且 \\(P=NP\\) 仍可能假（最坏难、平均易）。电路课的自然证明：太强的下界会破坏 OWF。复杂性单元以此收束经典平均，下一课量子 BQP 只给直觉。",-1)),a[5]||(a[5]=n("p",null,"判定「一个函数是不是单向」是一场实验，不是一句口号：",-1)),(r(),l(E,null,{default:e(()=>[s(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20GEN%5B%22%E5%9D%87%E5%8C%80%E9%9A%8F%E6%9C%BA%E6%8A%BD%20x%22%5D%20--%3E%20CAL%5B%22%E7%AE%97%20y%20%3D%20f(x)%22%5D%0A%20%20CAL%20--%3E%20ADV%5B%22%E5%AF%B9%E6%89%8B%E5%8F%AA%E7%9C%8B%20y%2C%20%E8%BE%93%E5%87%BA%20x'%22%5D%0A%20%20ADV%20--%3E%20CHK%7B%22f(x')%20%3D%20y%20%3F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%88%90%E5%8A%9F%E6%A6%82%E7%8E%87%E5%8F%AF%E5%BF%BD%E7%95%A5%22%7C%20SEC%5B%22f%20%E6%98%AF%E5%8D%95%E5%90%91%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%A6%82%E7%8E%87%E4%B8%8D%E5%8F%AF%E5%BF%BD%E7%95%A5%22%7C%20BRO%5B%22f%20%E8%A2%AB%E6%94%BB%E7%A0%B4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">数字实例：若 \\(P=NP\\)，对手就能在多项式时间解「给定 \\(y\\) 找 \\(x&#39;\\)」，任何 OWF 立刻全军覆没。所以 OWF 存在 \\(\\Rightarrow P\\neq NP\\)；它还更强——难必须出现在随机抽样实例的平均上，而不仅是最坏实例。</span></p><p>Håstad–Impagliazzo–Levin–Luby：OWF 存在则有 PRG。私钥加密的极小假设常落到这里。陷门置换额外要求「有密钥可逆」，RSA 形状；OWF 不必有陷门。Ajtai 的格给了最坏到平均的稀有例子，LWE 课再写。NPC 随机实例易，不推翻最坏完全性。</p><p><span class="marginnote">常见误区：初学者容易把「单向」与「有陷门」混为一谈。哈希、大数相乘都像单向函数，但没有任何「钥匙」能反演；陷门置换（RSA 形状）额外要求握着私钥就能轻易倒着算。单向不蕴涵陷门——公钥加密需要的恰恰是后者。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 PRG 构造，不引入 CCA。不把哈希当 OWF（哈希是设计目标，不是已证）。后课默认：密码学平均难 \\(\\ne\\) NPC；OWF 是极小假设。下一课 BQP。</p><p>最坏 NPC 不导出平均难，更不导出 OWF。密码学要的是抽样实例上的反演失败。自然证明与电路下界的张力在此咬合：太强的组合下界会破坏伪随机。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>平均情形要分布；最坏完全性不够。</li><li>OWF：正算易，平均反演难；蕴涵 \\(P\\neq NP\\) 且更强。</li><li>最坏到平均的归约是稀有结构，不是 NPC 赠品。</li><li>后课格上 LWE 才给出稀有的最坏到平均。</li><li>出处：Levin；Goldreich；Arora and Barak。</li></ul>',8))])}const D=d(B,[["render",P]]);export{C as __pageData,D as default};
